// src/utils/helpers.js
export const calcularAntiguedad = (fechaIngreso) => {
  if (!fechaIngreso) return 0;
  const ingreso = new Date(fechaIngreso);
  const ahora = new Date();
  let años = ahora.getFullYear() - ingreso.getFullYear();
  const mes = ahora.getMonth() - ingreso.getMonth();
  if (mes < 0 || (mes === 0 && ahora.getDate() < ingreso.getDate())) {
    años--;
  }
  return años;
};
